ALTER TABLE "enrollment_grants" DROP CONSTRAINT "enrollment_grants_source_shape_check";--> statement-breakpoint
CREATE UNIQUE INDEX "enrollment_grants_free_user_course_unique_idx" ON "enrollment_grants" USING btree ("user_id","course_id") WHERE "enrollment_grants"."source_type" = 'free_enrollment';--> statement-breakpoint
ALTER TABLE "enrollment_grants" ADD CONSTRAINT "enrollment_grants_source_shape_check" CHECK (("enrollment_grants"."source_type" = 'paid_order' and "enrollment_grants"."order_id" is not null and "enrollment_grants"."manual_reference" is null) or ("enrollment_grants"."source_type" = 'manual' and "enrollment_grants"."order_id" is null and "enrollment_grants"."manual_reference" is not null) or ("enrollment_grants"."source_type" = 'free_enrollment' and "enrollment_grants"."order_id" is null and "enrollment_grants"."manual_reference" is null));